// === Tab: sketch.js ===
let mandelbulbShader;

const cameraData = {
  dist: 3.0,
  rotX: 0.37,
  rotY: 0.37,
  target: [0, 0, 0],
  last: {}
};

const interaction = {
  isDragging: false,
  isPanning: false,
  startX: 0,
  startY: 0,
  startRotX: 0,
  startRotY: 0,
  startTarget: [0, 0, 0]
};

const settings = {
  resolution: 1.0,
  iterations: 64
};

function preload() {
  mandelbulbShader = loadShader('https://openprocessing.org/sketch/2846937/files/vert.glsl', 'frag.glsl');
}

function setup() {
  const canvasSize = max(windowWidth, windowHeight);
  createCanvas(windowWidth, windowHeight, WEBGL);

  pixelDensity(1);
  noStroke();

  syncLastParams();
}

function windowResized() {
  var canvasSize = max(windowWidth, windowHeight);
  resizeCanvas(canvasSize, canvasSize);
}

function draw() {
  shader(mandelbulbShader);

  const uniforms = {
    'u_resolution': [width, height],
    'u_camDist': cameraData.dist,
    'u_camRotX': cameraData.rotX,
    'u_camRotY': cameraData.rotY,
    'u_camTarget': cameraData.target,
    'u_maxIter': settings.iterations,
    'u_renderScale': settings.resolution
  };

  Object.entries(uniforms).forEach(([name, val]) => {
    mandelbulbShader.setUniform(name, val);
  });

  rect(-width / 2, -height / 2, width, height);

  if (hasViewChanged()) {
    syncLastParams();
  }
}


function handleInputStart() {
  interaction.isDragging = true;
  interaction.isPanning = keyIsDown(SHIFT);
  interaction.startX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  interaction.startY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
  interaction.startRotX = cameraData.rotX;
  interaction.startRotY = cameraData.rotY;
  interaction.startTarget = [...cameraData.target];
  return false;
}

function handleInputMove() {
  if (!interaction.isDragging) return;

  const dx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - interaction.startX;
  const dy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - interaction.startY;

  if (interaction.isPanning) {
    const panSpeed = cameraData.dist * 0.002;
    const right = [cos(interaction.startRotY), 0, sin(interaction.startRotY)];
    const up = [0, 1, 0];

    cameraData.target[0] = interaction.startTarget[0] - right[0] * dx * panSpeed - up[0] * dy * panSpeed;
    cameraData.target[1] = interaction.startTarget[1] - right[1] * dx * panSpeed - up[1] * dy * panSpeed;
    cameraData.target[2] = interaction.startTarget[2] - right[2] * dx * panSpeed - up[2] * dy * panSpeed;
  } else {
    cameraData.rotY = interaction.startRotY - dx * 0.0075;
    cameraData.rotX = constrain(interaction.startRotX + dy * 0.0075, -PI / 2 + 0.01, PI / 2 - 0.01);
  }
  return false;
}

function handleInputEnd() {
  interaction.isDragging = false;
  interaction.isPanning = false;
  return false;
}

function mousePressed() { return handleInputStart(); }
function mouseDragged() { return handleInputMove(); }
function mouseReleased() { return handleInputEnd(); }

function touchStarted() { return handleInputStart(); }
function touchMoved() { return handleInputMove(); }
function touchEnded() { return handleInputEnd(); }

function mouseWheel(event) {
  cameraData.dist = constrain(cameraData.dist * (event.delta < 0 ? 0.9 : 1.1), 0.1, 20.0);
  return false;
}

function keyPressed() {
  if (key.toLowerCase() === 'r') {
    cameraData.dist = 3.0;
    cameraData.rotX = 0.3;
    cameraData.rotY = 0.5;
    cameraData.target = [0, 0, 0];
  }
}

function hasViewChanged() {
  return cameraData.dist !== cameraData.last.dist ||
         cameraData.rotX !== cameraData.last.rotX ||
         cameraData.rotY !== cameraData.last.rotY ||
         cameraData.target.some((v, i) => v !== cameraData.last.target[i]);
}

function syncLastParams() {
  cameraData.last = {
    dist: cameraData.dist,
    rotX: cameraData.rotX,
    rotY: cameraData.rotY,
    target: [...cameraData.target]
  };
}

// === Tab: vert.glsl ===
precision highp float;
attribute vec3 aPosition;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}

// === Tab: frag.glsl ===
precision highp float;

uniform vec2 u_resolution;
uniform float u_camDist;
uniform float u_camRotX;
uniform float u_camRotY;
uniform vec3 u_camTarget;
uniform float u_maxIter;
uniform float u_renderScale;

const float POWER = 8.0;
const float BAILOUT = 2.0;
const float MAX_STEPS = 256.0;
const float MIN_DIST = 0.0001;
const float MAX_DIST = 256.0;

float mandelbulbDE(vec3 pos) {
  vec3 z = pos;
  float dr = 1.0;
  float r = 0.0;

  for (float i = 0.0; i < 4096.0; i++) {
    if (i >= u_maxIter) break;

    r = length(z);
    if (r > BAILOUT) break;

    float theta = acos(z.z / r);
    float phi = atan(z.y, z.x);
    dr = pow(r, POWER - 1.0) * POWER * dr + 1.0;

    float zr = pow(r, POWER);
    theta = theta * POWER;
    phi = phi * POWER;

    z = zr * vec3(
      sin(theta) * cos(phi),
      sin(theta) * sin(phi),
      cos(theta)
    );
    z += pos;
  }

  return 0.5 * log(r) * r / dr;
}

vec3 estimateNormal(vec3 p) {
  float eps = 0.0005;
  return normalize(vec3(
    mandelbulbDE(p + vec3(eps, 0, 0)) - mandelbulbDE(p - vec3(eps, 0, 0)),
    mandelbulbDE(p + vec3(0, eps, 0)) - mandelbulbDE(p - vec3(0, eps, 0)),
    mandelbulbDE(p + vec3(0, 0, eps)) - mandelbulbDE(p - vec3(0, 0, eps))
  ));
}

mat3 rotateX(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat3(
    1.0, 0.0, 0.0,
    0.0, c, -s,
    0.0, s, c
  );
}

mat3 rotateY(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat3(
    c, 0.0, s,
    0.0, 1.0, 0.0,
    -s, 0.0, c
  );
}

void main() {
  vec2 pixelCoord = floor(gl_FragCoord.xy / u_renderScale) * u_renderScale;
  vec2 uv = (pixelCoord - u_resolution * 0.5) / u_resolution.y;

  vec3 offset = vec3(0.0, 0.0, u_camDist);
  offset = rotateX(u_camRotX) * offset;
  offset = rotateY(u_camRotY) * offset;
  vec3 camPos = u_camTarget + offset;

  vec3 forward = normalize(u_camTarget - camPos);
  vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
  vec3 up = cross(forward, right);

  vec3 rayDir = normalize(forward + uv.x * right + uv.y * up);

  float totalDist = 0.0;
  vec3 pos = camPos;
  bool hit = false;
  float steps = 0.0;

  for (float i = 0.0; i < MAX_STEPS; i++) {
    float dist = mandelbulbDE(pos);
    totalDist += dist;
    pos += rayDir * dist;
    steps++;

    if (dist < MIN_DIST * totalDist) {
      hit = true;
      break;
    }

    if (totalDist > MAX_DIST) break;
  }

  vec3 colour = vec3(0.0);

  if (hit) {
    vec3 normal = estimateNormal(pos);
    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
    vec3 viewDir = normalize(camPos - pos);

    float diff = max(dot(normal, lightDir), 0.0);
    float ambient = 0.15;
    float ao = 1.0 - (steps / MAX_STEPS);

    vec3 baseColour = vec3(0.9, 0.9, 0.9);
    colour = baseColour * (ambient + diff * 0.7) * ao;

    vec3 halfDir = normalize(lightDir + viewDir);
    float spec = pow(max(dot(normal, halfDir), 0.0), 40.0);
    colour += vec3(spec * 0.6);

    float fresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 3.0);
    colour += vec3(0.2, 0.3, 0.4) * fresnel * 0.3;
  } else {
    float fog = smoothstep(0.0, 1.0, totalDist / MAX_DIST);
    colour = mix(vec3(0.15, 0.15, 0.2), vec3(0.0), fog);
  }

  gl_FragColor = vec4(colour, 1.0);
}

